  function aiMemoryProgressLabel(room,area){
    const config=aiMemoryConfig(room),row=config.areas[area],count=aiMemoryRuntime.lastCounts.get(String(room.chatId))?.[area];
    const on=config.enabled&&row.enabled;
    if(count==null)return `${on?'수집 확인 중':'자동 OFF'} · 주기 ${row.interval}턴`;
    const ready=aiMemoryRuntime.lastCounts.get(String(room.chatId))?.ready?.[area]??count;
    return `${row.draft?'검토 대기':row.error?'확인 필요':on?'수집 중':'자동 OFF · 호출 중지'} · 수집 ${ready} / ${row.interval}턴${count>ready?` · 미처리 ${count}턴`:''} · 다음 생성까지 ${Math.max(0,row.interval-ready)}턴`;
  }
  async function aiMemorySetEnabled(room,area,enabled,control){
    const config=aiMemoryConfig(room),row=config.areas[area],oldEnabled=row.enabled,oldGlobal=config.enabled,oldBaseline=row.baseline;
    if(control)control.disabled=true;
    try{if(enabled&&!row.cursor&&!row.baseline&&!wishHistoryActive(room,area)){const turns=await loadLatestCompletedTurns(room),last=turns.at(-1);row.baseline=String(last?.key||'');aiMemorySetAnchorEvidence(room,area,last,true);}
      row.applyRevision++;row.enabled=enabled;if(enabled)config.enabled=true;else if(!Object.values(config.areas).some(value=>value.enabled))config.enabled=false;
      await saveRoom(room);aiMemoryRefreshStatusUi(room);
      state.modal?.querySelectorAll('[data-ai-memory-enable]').forEach(input=>input.checked=config.areas[input.dataset.aiMemoryEnable].enabled);
      const master=state.modal?.querySelector('[data-ai-memory-global]');if(master)master.checked=config.enabled;
      if(enabled)void aiMemoryPoll(room,true);
    }catch(error){row.enabled=oldEnabled;row.baseline=oldBaseline;config.enabled=oldGlobal;if(control?.matches('input'))control.checked=oldEnabled;aiMemoryRefreshStatusUi(room);notify(`자동 정리 설정 실패: ${error.message}`,'error');}
    finally{if(control)control.disabled=false;}
  }

