    const auditButton=root.querySelector('.wish-three-audit');if(auditButton){auditButton.disabled=!!audit?.busy;auditButton.textContent=audit?.at&&!audit?.error?'↻ 새로고침':audit?.error?'다시 확인':'정리 현황 확인';}

    set('[data-wish-turn-total]',audit?.busy?'조회 중':audit?.error?'조회 실패':Number.isInteger(audit?.total)?`${audit.total.toLocaleString('ko-KR')}턴`:'조회 전');
    set('[data-wish-turn-processed]',audit?.busy?'—':coverage?`${coverage.all} / ${coverage.total}턴`:'확인 중');
    set('[data-wish-turn-unprocessed]',audit?.busy?'—':coverage?`${coverage.remaining}턴`:'확인 중');
    const auditNote=audit?.busy?audit.progress||'완료 턴 조회 중…':audit?.error?`조회 실패: ${audit.error}`:audit?.at?`마지막 조회 ${new Date(audit.at).toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit'})} · 필요하면 새로고침`:'진행 턴을 서버에서 조회해 표시합니다';
