      const tabKey={currentState:'state',logSummary:'logs',timeline:'timeline'}[key],label=WISH_CLEAN_AREAS.find(([id])=>id===key)?.[1]||'';
      root.querySelectorAll(`[data-clean-auto-enable="${key}"]`).forEach(input=>{input.checked=row.enabled;});
