  async function wishCleanRefreshTurnAudit(room,force=false){
    const id=String(room.chatId),old=wishCleanTurnAudits.get(id);
    if(!force&&old?.at&&!old?.error&&Date.now()-old.at<WISH_CLEAN_AUDIT_TTL_MS){wishCleanUpdateStatus(room);return old;}
    if(wishCleanTurnAuditInflight.has(id))return wishCleanTurnAuditInflight.get(id);
    const task=(async()=>{
      const snapshot={busy:true,progress:'완료된 USER+AI 턴 조회 중…'};
      wishCleanTurnAudits.set(id,snapshot);wishCleanUpdateStatus(room);
      try{
        const turns=await loadRpcmCompletedRange(room,[],{onProgress:({messages,done})=>{snapshot.progress=`${messages.toLocaleString('ko-KR')}개 메시지 확인 ${done?'완료':'중'}`;wishCleanUpdateStatus(room);}});
        if(state.currentRoom!==room)throw new Error('조회 중 RP 방이 바뀌었습니다.');
        const indices=new Map();turns.forEach((turn,index)=>{indices.set(String(turn.key),index);for(const alias of turn.aliases||[])indices.set(String(alias),index);});
        const record={total:turns.length,indices,turnKeys:turns.map(t=>String(t.key)),sourceHashes:new Map(turns.map(t=>[String(t.key),simpleHash(String(t.text))])),anchorHashes:new Map(turns.map(t=>[String(t.key),aiMemoryAnchorFingerprint(t)])),at:Date.now(),busy:false};wishCleanTurnAudits.set(id,record);wishCleanUpdateStatus(room);return record;
      }catch(error){const record={error:String(error?.message||error),at:Date.now(),busy:false};wishCleanTurnAudits.set(id,record);wishCleanUpdateStatus(room);return record;}
      finally{wishCleanTurnAuditInflight.delete(id);}
    })();
    wishCleanTurnAuditInflight.set(id,task);return task;
  }
