  async function init() {
    if (!wishBoot.begin()) return;
    wishBoot.status('initializing', '화면 초기화 중');
    try {
      addStyles();
      addAiSummaryStyles();
      addCompactDesignStyles();
      addManualUpdateDesignStyles();
      addWishUiStyles();
      addRpcmCoreStyles();
      addRpcm74Styles();
      bindViewportMetrics();
      bindPerformanceVisibility();
      bindMobileSettingsMenuEntry();
      bindRerollBridge();
      wishBoot.status('storage', '저장소 연결 대기 중 · 기존 자료는 유지됩니다');
      state.db = await openDb();
      wishBoot.status('room', '채팅방 자료를 준비하는 중');
      await compactMigrateStoredData();
      GM_addStyle(INTEGRATED_UI_CSS);
      wishCleanUiStyle();
      wishTabbedStyles();
      wishMemoryFlowStyles();
      wishQualityStyles();
      wishEasyStyles();
      wishBindMessageMemory();
      createFab();
      startRenderedContextObserver();
      await ensureCurrentRoom(getChatIdFromPath(), true);
      bindWishAiBridge();
      await cleanOrphanMarkerInCurrentRoom();
      scheduleRouteTick();
      // 새로고침 후에도 활성 자동 유지 세션을 이어가기 위한 즉시 복구 패스입니다.
      scheduleRecovery(0);
      wishBoot.status('ready', '준비 완료');
      console.log(`[위시RPManager] ${APP.name} v${APP.version} loaded`);
    } catch (e) {
      wishBoot.fail(e);
      console.error('[RP매니저] init failed', e);
      notify(`🪽위시 RP Manager 초기화 실패: ${e.message}`, 'error', 7000);
    }
  }

  function startCompat() {
    // 기본은 기존 상단 위치를 사용합니다. 해당 DOM이 아직 준비되지 않았으면 임시 폴백을 쓰고,
    // 실제 충돌로 버튼이 제거되는 경우에만 그 페이지 세션에서 독립 폴백으로 전환합니다.
    setTimeout(() => init(), 250);
  }

  // 화면 숨김 필터는 Manager UI보다 먼저 시작합니다.
  startRenderedContextObserver();

  // UI 탐색만 공유합니다. 다른 확장의 DOM과 페이지 저장소를 변경하지 않습니다.
  window.__WISH_RP_MANAGER_UI_BRIDGE__ = Object.freeze({
    headerActionRow:findStableCrackHeaderActionRow,
    isVisible:isCrackHeaderVisible,
    canMountHeader:canMountCrackHeaderButton,
  });
  try {
    GM_registerMenuCommand('🪽 RP Manager 열기', () => openModal().catch(error => notify(error.message, 'error')));
  } catch (_) {}

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', startCompat, { once: true });
    window.addEventListener('load', startCompat, { once: true });
  } else {
    startCompat();
  }
  setTimeout(() => { if (document.readyState !== 'loading') startCompat(); }, 1200);

